  string folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../artifacts"));yield return new WaitForSeconds(.3f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"cockpit-mirrors.png"));yield return new WaitForSeconds(.3f);
